</head>
<body>
  <div class="container">
    <h1>Todo List</h1>
    <form class="todo-form" id="todo-form">
      <input type="text" id="todo-input" class="todo-input" placeholder="What needs to be done?" autocomplete="off" required />
      <button type="submit" class="btn btn-primary">Add</button>
    </form>

    <div class="controls">
      <span class="counter" id="counter">0 items left</span>
      <div class="filters">
        <button type="button" class="filter-btn active" data-filter="all">All</button>
        <button type="button" class="filter-btn" data-filter="active">Active</button>
        <button type="button" class="filter-btn" data-filter="completed">Completed</button>
      </div>
    </div>

    <ul class="todo-list" id="todo-list"></ul>
    <div class="empty-state" id="empty-state" style="display: none;">No tasks found</div>
  </div>

  <script>
    (function () {
      const STORAGE_KEY = 'todos_data';
      let todos = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
      let currentFilter = 'all';

      const form = document.getElementById('todo-form');
      const input = document.getElementById('todo-input');
      const list = document.getElementById('todo-list');
      const counter = document.getElementById('counter');
      const emptyState = document.getElementById('empty-state');
      const filterBtns = document.querySelectorAll('.filter-btn');

      function save() {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
      }

      function render() {
        const filtered = todos.filter(todo => {
          if (currentFilter === 'active') return !todo.completed;
          if (currentFilter === 'completed') return todo.completed;
          return true;
        });

        list.innerHTML = '';
        if (filtered.length === 0) {
          emptyState.style.display = 'block';
        } else {
          emptyState.style.display = 'none';
          filtered.forEach(todo => {
            const li = document.createElement('li');
            li.className = `todo-item ${todo.completed ? 'completed' : ''}`;

            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.className = 'todo-checkbox';
            checkbox.checked = todo.completed;
            checkbox.addEventListener('change', () => toggleTodo(todo.id));

            const textSpan = document.createElement('span');
            textSpan.className = 'todo-text';
            textSpan.textContent = todo.text;

            const delBtn = document.createElement('button');
            delBtn.className = 'delete-btn';
            delBtn.innerHTML = '&times;';
            delBtn.title = 'Delete todo';
            delBtn.addEventListener('click', () => deleteTodo(todo.id));

            li.appendChild(checkbox);
            li.appendChild(textSpan);
            li.appendChild(delBtn);
            list.appendChild(li);
          });
        }

        const activeCount = todos.filter(t => !t.completed).length;
        counter.textContent = `${activeCount} item${activeCount === 1 ? '' : 's'} left`;
      }

      function addTodo(text) {
        todos.push({
          id: Date.now().toString(),
          text: text.trim(),
          completed: false
        });
        save();
        render();
      }

      function toggleTodo(id) {
        todos = todos.map(todo => 
          todo.id === id ? { ...todo, completed: !todo.completed } : todo
        );
        save();
        render();
      }

      function deleteTodo(id) {
        todos = todos.filter(todo => todo.id !== id);
        save();
        render();
      }

      form.addEventListener('submit', (e) => {
        e.preventDefault();
        const text = input.value.trim();
        if (text) {
          addTodo(text);
          input.value = '';
        }
      });

      filterBtns.forEach(btn => {
        btn.addEventListener('click', () => {
          filterBtns.forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
          currentFilter = btn.dataset.filter;
          render();
        });
      });

      render();
    })();
  </script>
</body>
</html>"}
